---StrIsEmpty
---检查字符串是否是空的
---@param str string
function GuideUtils.StrIsEmpty(str)
    return string.isEmpty(str) or str == "0"
end

---ParsePosition
---解析位置信息
---@param posStr string 位置信息字符串
function GuideUtils.ParsePosition(posStr)
    local isEmpty = GuideUtils.StrIsEmpty(posStr)
    local x, y = 0, 0
    if not isEmpty then
        x, y = SafeUnpack(parse_strings(posStr, ","))
    end
    return Vector2.New(checkNumber(x), checkNumber(y))
end

---CheckIsCompleteGuideByModuleId
---@param moduleId number 模块id
function GuideUtils.CheckIsCompleteGuideByModuleId(moduleId)
    local AppEngine = CS.Engine.Lib.AppEngine
    local IsOpenGuide = AppEngine.GetConfig("Engine.Dev", "IsOpenGuide")
    ---@type GuideComponent
    local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
    return tonumber(IsOpenGuide) == 0 or guideComponent:CheckOneCondition(Constants.GuideConditionType.CompleteSpecifyModule, moduleId)
