---ShowGuideModuleTipsBySystemFuncId
---@param systemFuncId number 系统功能表id
---@return boolean isShowTips 是否显示提示
function GuideUtils.ShowGuideModuleTipsBySystemFuncId(systemFuncId)

    if not GuideUtils.IsInGuiding() then
        return false
    end
    ---@type GuideComponent
    local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
    local curExecuteModule = guideComponent:GetCurExecuteModule()
    if curExecuteModule == nil then
        return
    end
    local systemFunction   = curExecuteModule.systemFunction
    if systemFunction == 0 then
        return false
    end

    if systemFunction ~= checkNumber(systemFuncId) then
        GuideUtils.ShowGuideModuleTips()
        return true
    end

    return false
end

---ShowGuideModuleTips
function GuideUtils.ShowGuideModuleTips(moduleStepVo)
    local node = UIModule.RootCanvas.transform:Find("UISystemGuideTipsBoard")
    if node then
        return
    end
    ---@type GuideComponent
    local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
    ---@type SystemGuideModuleStepVo
    local stepVo = moduleStepVo or guideComponent:GetCurExecuteModuleStepVo()
    if stepVo == nil or stepVo.dialogType ~= Constants.GuideDialogType.NoMask then
        return
    end
    local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.UISystemGuideTipsBoard, UIModule.RootCanvas.gameObject)
    if isNull(go) then
        return
    end
    ---@type UISystemGuideTipsBoard
    local env = CfUtils.GetLuaScr(go, "Game.UI.Guide.UISystemGuideTipsBoard")
    if isNull(env) then
        return
    end
    env:RefreshUI(stepVo)
    -- env:SetLoader(loader)
end

---InitBattleSelectionTabData
--- 初始化战斗选择标签页数据
--- copy BattleSelectionDialog:InitData()
function GuideUtils.InitBattleSelectionTabData()
    local t = CfUtils.GetCfTable(AutoIds.IdSetting1602)
    if t == nil then
        return
    end
    local allVo = {}
    local ActionTypeVo = import("Game.Setting.Vo.ActionTypeVo")
    for k, v in pairs(t) do
        local vo = ActionTypeVo.New()
        vo:FillVo(v)
        if not allVo[checkString(vo.tab)] then
            allVo[checkString(vo.tab)] = {}
        end
        table.insert(allVo[checkString(vo.tab)], vo)
    end

    for k, v in pairs(allVo) do
        table.sort(v, function(a, b)
            return checkNumber(a.order) < checkNumber(b.order)
        end)
        if #(v) > 1 then
            for i = 1, #(v) do
                for j = i + 1, #(v) do
                    local fd = v[i]
                    local td = v[j]
                    if GameUtils.IsUnlockedBySystemTogId(checkNumber(td.id)) and not GameUtils.IsUnlockedBySystemTogId(checkNumber(fd.id)) then
                        local d = fd
                        v[j] = d
                        v[i] = td
                    end
                end
            end
        end
    end
    return allVo
end

---GetSignboardPosBySignboardId
--- 根据看板娘id获得看板娘位置
---@param signboardId number 看板娘角色表 id
---@return number posId: 看板娘位置
function GuideUtils.GetSignboardPosBySignboardId(signboardId)
    ---@type RoleShowVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", signboardId)
    local posT = CfUtils.Split(vo.position) 
    if next(posT) == nil then return end
    local num = checkInt(math.random(1, #posT))
    local posId = posT[num]
    return posId
end

---ShowSignboardBySignboardId
---根据看板娘id显示看板娘
---@param signboardId number 看板娘角色表 id
function GuideUtils.UpdateSignboardShowStateBySignboardId(signboardId, isShow)
    local posId = GuideUtils.GetSignboardPosBySignboardId(signboardId)
    if posId == nil then return end
    Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, {isTrue = not isShow})
    Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = not isShow, roleId = signboardId})
    local RolesShowMgr = import('Game.Robot.RolesShowMgr')
    RolesShowMgr:GetInstance():SetMainHomeCameraActivity(not isShow)
    yield_return(RolesShowMgr:GetInstance():SetCameraActivity(isShow, "10"..posId))
end

