---CheckPivot
---检查描点
---@param node UnityEngine.RectTransform
---@param func fun():void
function GuideUtils.CheckPivot(node, func)
    local pivot = node.pivot
    local isNeedChange = pivot.x ~= CenterPivot.x or pivot.y ~= CenterPivot.y
    --- 如果 pivot 不是 0.5,0.5 则修正
    if isNeedChange then
        node:SetPivot(CenterPivot)
    end
    if func then
        func()
    end
    --- 恢复
    if isNeedChange then
        node:SetPivot(pivot)
    end
end

---CheckPivotByNodes
---根据节点列表检查描点
---@param nodes UnityEngine.RectTransform[]
---@param func fun():void
function GuideUtils.CheckPivotByNodes(nodes, func)
    local t = {}
    for i, node in ipairs(nodes) do
        local pivot = node.transform.pivot
        local isNeedChange = pivot.x ~= CenterPivot.x or pivot.y ~= CenterPivot.y
        if isNeedChange then
            t[i] = pivot
            node:SetPivot(CenterPivot)
        end
    end
    if func then
        func()
    end
    if next(t) ~= nil then
        for i, pivot in pairs(t) do
            nodes[i].transform:SetPivot(pivot)
        end
    end
end

---SetRegionParams
---设置区域参数
---@param rt UnityEngine.RectTransform
---@param params table
---@param startIndex number
function GuideUtils.SetRegionParams(rt, params, startIndex)
    local x, y = checkNumber(params[startIndex]), checkNumber(params[startIndex + 1])
    local w, h = checkNumber(params[startIndex + 2]), checkNumber(params[startIndex + 3])
    local anchorMaxX = params[startIndex + 4] and checkNumber(params[startIndex + 4]) or 0.5
    local anchorMaxY = params[startIndex + 5] and checkNumber(params[startIndex + 5]) or 0.5
    local anchorMinX = params[startIndex + 6] and checkNumber(params[startIndex + 6]) or 0.5
    local anchorMinY = params[startIndex + 7] and checkNumber(params[startIndex + 7]) or 0.5
    rt.anchorMax = Vector2.New(anchorMaxX, anchorMaxY)
    rt.anchorMin = Vector2.New(anchorMinX, anchorMinY)
    rt.sizeDelta = Vector2.New(w, h)
    rt.anchoredPosition = Vector3.New(x, y)
end

---GetHighlightNode
---获得节点
---@param nodePath string 节点路径 prefabName/childName  例： UICultivateEquipComparedView/CompareIntroductionNode/BottomNode/BottomButtons/CultivateButton
---@param nodeType number 节点类型 0. ui节点 1. 非ui节点
function GuideUtils.GetNode(nodePath, nodeType)
    local rootTransform = UIModule.RootCanvas.transform
    local highlightNode
    nodeType = checkNumber(nodeType)
    local unscaledTime = Time.unscaledTime
    local count = 0

    local prefabName
    local index = string.find(nodePath, '/', 1)
    if index ~= nil then 
        prefabName = string.sub(nodePath, 1, index)
    end 

    while true do
        if nodeType == NodeType.UI then
            if prefabName and IsEnableUseWorldCanvas then 
                local prefabTrans = rootTransform:Find(prefabName)
                if not isNull(prefabTrans) then 
                    local useParent = KTool.GetComponent(prefabTrans.gameObject, typeof(CS.Game.Native.UseWorldCanvasParent))

                    if not isNull(useParent) then 
                        highlightNode = useParent:FindNode(nodePath)
                    end 
                end 
            end 
            
            if isNull(highlightNode) then 
                highlightNode = rootTransform:Find(nodePath)
            end 
        else
            local go = GameObject.Find(nodePath)
            if not isNull(go) then
                highlightNode = go.transform
            end
        end

        if highlightNode == nil then
            yield_return()
            if Time.unscaledTime - unscaledTime >= 1 then
                unscaledTime = Time.unscaledTime
                count = count + 1
                if count > 5 then
                    printError("找不到节点路径 ->> %s", nodePath)
                    break
                end
            end
        else
            break
        end
    end
    return highlightNode
end

---GetListCell
---@param listPath  string   列表路径
---@param nodeIndex number   节点下标
---@param cellPath  string   cell路径
---@param isMove    boolean  是否移动到指定下标
---@param subCellIndex    boolean  子cell下标
---@param nodeType  integer  节点类型  NodeType
function GuideUtils.GetListCell(listPath, nodeIndex, cellPath, isMove, subCellIndex, nodeType)
    local node     = GuideUtils.GetNode(listPath, nodeType)
    local isNull = isNull
    if isNull(node) then
       return 
    end
    local listNode = node.gameObject
    ---@type SuperScrollView.LoopListView2
    local comp = KTool.GetComponent(listNode, LoopGridViewType) or KTool.GetComponent(listNode, LoopListView2Type)
    if comp == nil then
        comp = KTool.GetComponent(listNode, FancyScrollViewType)
    end
    local index = math.max(checkNumber(nodeIndex), 0)
    if isMove then
        local MovePanelFunc = comp.MovePanelToItemIndex or comp.MovePanelToItemByIndex or comp.MovePanelToIndex
        if MovePanelFunc then
            MovePanelFunc(comp, index)
        end
    end

    local item = comp:GetShownItemByItemIndex(index)
    local CoYield = CoYield
    while isNull(item) do
        CoYield()
        item = comp:GetShownItemByItemIndex(index)
    end
    local node
    if item then
        if checkNumber(subCellIndex) > 0 then
            item = item.transform:GetChild(subCellIndex - 1)
        end

        if cellPath and cellPath ~= "0" then
            local childNode = item.transform:Find(cellPath)
            node = childNode
        else
            node = item
        end
    end
    return node
end

