--- InitGuideRole
--- 初始化引导人物
function GuideUtils.InitGuideRole(func)
    local go = GameObject.Find("GuideCameraNode")
    if isNull(go) then
        ---相机节点
        ---@type UnityEngine.GameObject
        go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.GuideCameraNode)
        go.transform.localPosition = Vector3.New(1000, 1000, 1000)
        local camera = go.gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
        ---小白
        local smallWhiteGo        = GameUtils.LoadBundleSync("Arts/Prefab/10801.prefab", go.gameObject)
        local comp = KTool.GetOrAddComponent(smallWhiteGo.gameObject, typeof(CS.CustomLightDirRelativeCamera))
        comp.UsrCustomLightColor = true
        comp.RelativeCamera = camera
        KTool.SetLayer(go.gameObject, smallWhiteGo.gameObject, true)
        smallWhiteGo.transform.localPosition = Vector3.New(0.012, -0.182, -0.018)
        smallWhiteGo.transform.localRotation = Quaternion.Euler(10.86442, 180, -5)
        smallWhiteGo.transform.localScale    = Vector3.New(0.5, 0.5, 1)
        if func then func(smallWhiteGo) end
    end
    return go
end

