function GuideUtils.CheckParentAnimatesByTransform(transform)
    if not KTool.IsActive(transform.gameObject) then
        return
    end
    ---@type UnityEngine.Animator[]
    local animators = transform:GetComponentsInParent(AnimatorType)
    GuideUtils.CheckAnimates(animators)

    ---@type UnityEngine.Animation[]
    local animations = transform:GetComponentsInParent(AnimationType)
    GuideUtils.CheckAnimations(animations)
    
end

function GuideUtils.CheckChildAnimatesByTransform(transform)
    if not KTool.IsActive(transform.gameObject) then
        return
    end

    ---@type UnityEngine.Animator[]
    local animators = transform:GetComponentsInChildren(AnimatorType)
    GuideUtils.CheckAnimates(animators)

    ---@type UnityEngine.Animation[]
    local animations = transform:GetComponentsInChildren(AnimationType)
    GuideUtils.CheckAnimations(animations)
end

function GuideUtils.CheckAnimates(animators)
    if not isNull(animators) and animators.Length > 0 then
        for i = 0, animators.Length - 1 do
            ---@type UnityEngine.Animator
            local animator = animators[i]
            if not KTool.IsNull(animator) and KTool.IsActiveInHierarchy(animator.gameObject) and animator.enabled and animator.runtimeAnimatorController and animator.runtimeAnimatorController.animationClips.Length > 0 then
                yield_return(animator:WaitUntilAniCompleted())
            end
        end
        
    end
end

function GuideUtils.CheckAnimations(animations)
    if not isNull(animations) and animations.Length > 0 then
        for i = 0, animations.Length - 1 do
            ---@type UnityEngine.Animation
            local animation = animations[i]
            while not KTool.IsNull(animation) and 
                  KTool.IsActiveInHierarchy(animation.gameObject) and 
                  animation.enabled and animation.wrapMode == Default and animation.isPlaying  do

                    local curPlayClip = GuideUtils.GetCurPlayClip(animation)
                    if not isNull(curPlayClip) and curPlayClip.wrapMode == Default then
                        yield_return()
                    else
                        break
                    end
            end
        end
        
    end
end

---GetCurPlayClip
---获取当前播放动画片段
---@param animation UnityEngine.Animation
---@return UnityEngine.AnimationClip
function GuideUtils.GetCurPlayClip(animation)
    if isNull(animation) then return end
    for _, animationState in pairs(animation) do
        if animation:IsPlaying(animationState.name) then
            return animationState.clip
        end
    end
end

function GuideUtils.GetGuideNodeRenderCameraByType(cameraType)
    local camera
    if cameraType == Constants.GuideNodeCameraType.MainCamera then
        camera = URPCameraController.mainCamera
    elseif cameraType == Constants.GuideNodeCameraType.WorldUICamera then
        camera = URPCameraController.worldUICamera
    elseif cameraType == Constants.GuideNodeCameraType.UICamera then
        camera = URPCameraController.uiCamera
    end
    return camera
end

